// Brevo's transactional webhook echoes back whatever `tags` were set at send
// time (see email-send's Call Brevo node) - that's how we know which
// prospect/step this event belongs to, since Brevo's payload otherwise only
// has the recipient's email address, not our internal ids.
//
// NOTE: Brevo's standard transactional webhook does not have a native
// "reply" event - that needs a separate inbound-parsing webhook, which
// isn't set up. Only opened/clicked/bounced map here; replies are not
// detected by this workflow today.
const body = $json.body;
const tags = body.tags || [];
const prospectTag = tags.find((t) => typeof t === 'string' && t.startsWith('prospect:'));
const stepTag = tags.find((t) => typeof t === 'string' && t.startsWith('step:'));
const prospectId = prospectTag ? Number(prospectTag.split(':')[1]) : null;
const stepId = stepTag ? Number(stepTag.split(':')[1]) : null;

const eventMap = {
  opened: 'opened',
  click: 'clicked',
  hard_bounce: 'bounced',
  soft_bounce: 'bounced',
  blocked: 'bounced',
  invalid_email: 'bounced',
  spam: 'bounced',
  unsubscribed: 'bounced',
};
const eventType = eventMap[body.event] || null;

return [{ json: {
  prospect_id: prospectId,
  step_id: stepId,
  event_type: eventType,
  payload: JSON.stringify(body),
} }];
